terraform {
  # use_lockfile (S3-native locking) requires Terraform 1.10 or later.
  required_version = ">= 1.10"

  # Partial configuration: bucket, key and region are supplied at init time so
  # that no account-specific values are committed, for example:
  #   terraform init -backend-config=backend.hcl
  # backend.hcl holds only non-secret metadata (bucket, key, region).
  # Credentials come from the environment or an assumed role, never from here.
  backend "s3" {
    encrypt      = true
    use_lockfile = true
  }
}

